+-fn path_prefix() -> String {
+-    match rust_paths::get_rust_root(None, false) {
+-        Ok(root) if root != "." && !root.is_empty() => {
+-            format!("{}/", root.trim_end_matches('/'))
+-        }
+-        _ => String::new(),
+-    }
+-}
