+    assert_eq!(sh.cwd, root);
+    assert_eq!(run_in(&mut sh, &["cd", "sub"], None).await.code, 0);
+    assert_eq!(run_in(&mut sh, &["cd"], None).await.code, 0);
+    assert_eq!(sh.cwd, root);
